using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // Get all shipments (dispatchers)
        group.MapGet("/", [Authorize] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new
                {
                    s.Id,
                    s.TrackingNumber,
                    s.Origin,
                    s.Destination,
                    Status = s.Status.ToString(),
                    s.CreatedAt,
                    s.EstimatedDelivery,
                    s.ActualDelivery,
                    s.CustomerEmail,
                    s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Get shipment by id
        group.MapGet("/{id:int}", [Authorize] async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            return Results.Ok(new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.ActualDelivery,
                shipment.CustomerEmail,
                shipment.Description
            });
        });

        // Track by tracking number (public)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null) return Results.NotFound();

            return Results.Ok(new
            {
                shipment.TrackingNumber,
                Status = shipment.Status.ToString(),
                shipment.Origin,
                shipment.Destination,
                shipment.EstimatedDelivery,
                shipment.ActualDelivery,
                shipment.Description
            });
        });

        // Create shipment (dispatchers)
        group.MapPost("/", [Authorize] async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                CustomerEmail = request.CustomerEmail,
                Description = request.Description,
                EstimatedDelivery = request.EstimatedDelivery,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            return Results.Created($"/api/shipments/{shipment.Id}", new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.CustomerEmail,
                shipment.Description
            });
        });

        // Update shipment status (dispatchers)
        group.MapPut("/{id:int}/status", [Authorize] async (int id, UpdateStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            if (Enum.TryParse<ShipmentStatus>(request.NewStatus, out var newStatus))
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                {
                    shipment.ActualDelivery = DateTime.UtcNow;
                }
                await db.SaveChangesAsync();
                return Results.Ok();
            }

            return Results.BadRequest("Invalid status");
        });

        // Delete shipment
        group.MapDelete("/{id:int}", [Authorize] async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            db.Shipments.Remove(shipment);
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

public record CreateShipmentRequest(
    string Origin,
    string Destination,
    string CustomerEmail,
    string Description,
    DateTime? EstimatedDelivery);

public record UpdateStatusRequest(string NewStatus);

