@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Shipment Management</PageTitle>

<h1>Shipment Management</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        <span class="bi bi-plus"></span> New Shipment
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Origin</label>
                        <InputText @bind-Value="newShipment.Origin" class="form-control" placeholder="City, State" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Destination</label>
                        <InputText @bind-Value="newShipment.Destination" class="form-control" placeholder="City, State" />
                    </div>
                </div>
                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Customer Email</label>
                        <InputText @bind-Value="newShipment.CustomerEmail" class="form-control" type="email" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate @bind-Value="newShipment.EstimatedDelivery" class="form-control" />
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label">Description</label>
                    <InputText @bind-Value="newShipment.Description" class="form-control" />
                </div>
                <button type="submit" class="btn btn-success me-2">Create</button>
                <button type="button" class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!filteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or customer..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in filteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.CustomerEmail</td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    @onchange="e => UpdateStatus(shipment.Id, e.Value?.ToString())">
                                <option value="">Change status...</option>
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                            <button class="btn btn-sm btn-outline-danger ms-1" @onclick="() => DeleteShipment(shipment.Id)">
                                Delete
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible mt-3">
        @message
        <button type="button" class="btn-close" @onclick="() => message = null"></button>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string? filterText;
    private bool showCreateForm;
    private CreateShipmentModel newShipment = new();
    private string? message;
    private bool isError;

    private IEnumerable<ShipmentDto> filteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.CustomerEmail.Contains(filterText, StringComparison.OrdinalIgnoreCase)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            message = $"Error loading shipments: {ex.Message}";
            isError = true;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        var request = new CreateShipmentRequest
        {
            Origin = newShipment.Origin,
            Destination = newShipment.Destination,
            CustomerEmail = newShipment.CustomerEmail,
            Description = newShipment.Description,
            EstimatedDelivery = newShipment.EstimatedDelivery
        };

        var response = await Http.PostAsJsonAsync("/api/shipments", request);
        if (response.IsSuccessStatusCode)
        {
            message = "Shipment created successfully!";
            isError = false;
            showCreateForm = false;
            newShipment = new();
            await LoadShipments();
        }
        else
        {
            message = "Error creating shipment.";
            isError = true;
        }
    }

    private async Task UpdateStatus(int id, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus)) return;

        var response = await Http.PutAsJsonAsync($"/api/shipments/{id}/status", new { NewStatus = newStatus });
        if (response.IsSuccessStatusCode)
        {
            message = $"Status updated to {newStatus}";
            isError = false;
            await LoadShipments();
        }
        else
        {
            message = "Error updating status.";
            isError = true;
        }
    }

    private async Task DeleteShipment(int id)
    {
        var response = await Http.DeleteAsync($"/api/shipments/{id}");
        if (response.IsSuccessStatusCode)
        {
            message = "Shipment deleted.";
            isError = false;
            await LoadShipments();
        }
        else
        {
            message = "Error deleting shipment.";
            isError = true;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private class CreateShipmentModel
    {
        public string Origin { get; set; } = string.Empty;
        public string Destination { get; set; } = string.Empty;
        public string CustomerEmail { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public DateTime? EstimatedDelivery { get; set; } = DateTime.Today.AddDays(5);
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@inject HttpClient Http

<PageTitle>Track Your Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p class="text-muted">Enter your tracking number to check shipment status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. SHP-20260701-100001"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<code>@searchedNumber</code>".
        Please verify your tracking number and try again.
    </div>
}

@if (result != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Tracking: <code>@result.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h6>Shipment Details</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Description</dt>
                        <dd class="col-sm-7">@result.Description</dd>

                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@result.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@result.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <h6>Delivery Information</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7">
                            <span class="badge @GetStatusBadgeClass(result.Status) fs-6">
                                @FormatStatus(result.Status)
                            </span>
                        </dd>

                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">
                            @if (result.EstimatedDelivery.HasValue)
                            {
                                @result.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")
                            }
                            else
                            {
                                <span class="text-muted">TBD</span>
                            }
                        </dd>

                        @if (result.ActualDelivery.HasValue)
                        {
                            <dt class="col-sm-5">Delivered On</dt>
                            <dd class="col-sm-7 text-success fw-bold">
                                @result.ActualDelivery.Value.ToString("MMMM dd, yyyy 'at' h:mm tt")
                            </dd>
                        }
                    </dl>
                </div>
            </div>

            <!-- Progress bar -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(result.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(result.Status)%"
                         aria-valuenow="@GetProgressPercentage(result.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(result.Status)
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string? searchedNumber;
    private TrackingResult? result;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        result = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");
            if (response.IsSuccessStatusCode)
            {
                result = await response.Content.ReadFromJsonAsync<TrackingResult>();
            }
            else
            {
                notFound = true;
            }
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

