@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Shipment Management</PageTitle>

<h1>Shipment Management</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        <span class="bi bi-plus"></span> New Shipment
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Origin</label>
                        <InputText @bind-Value="newShipment.Origin" class="form-control" placeholder="City, State" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Destination</label>
                        <InputText @bind-Value="newShipment.Destination" class="form-control" placeholder="City, State" />
                    </div>
                </div>
                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Customer Email</label>
                        <InputText @bind-Value="newShipment.CustomerEmail" class="form-control" type="email" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate @bind-Value="newShipment.EstimatedDelivery" class="form-control" />
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label">Description</label>
                    <InputText @bind-Value="newShipment.Description" class="form-control" />
                </div>
                <button type="submit" class="btn btn-success me-2">Create</button>
                <button type="button" class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!filteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or customer..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in filteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.CustomerEmail</td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    @onchange="e => UpdateStatus(shipment.Id, e.Value?.ToString())">
                                <option value="">Change status...</option>
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                            <button class="btn btn-sm btn-outline-danger ms-1" @onclick="() => DeleteShipment(shipment.Id)">
                                Delete
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible mt-3">
        @message
        <button type="button" class="btn-close" @onclick="() => message = null"></button>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string? filterText;
    private bool showCreateForm;
    private CreateShipmentModel newShipment = new();
    private string? message;
    private bool isError;

    private IEnumerable<ShipmentDto> filteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.CustomerEmail.Contains(filterText, StringComparison.OrdinalIgnoreCase)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            message = $"Error loading shipments: {ex.Message}";
            isError = true;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        var request = new CreateShipmentRequest
        {
            Origin = newShipment.Origin,
            Destination = newShipment.Destination,
            CustomerEmail = newShipment.CustomerEmail,
            Description = newShipment.Description,
            EstimatedDelivery = newShipment.EstimatedDelivery
        };

        var response = await Http.PostAsJsonAsync("/api/shipments", request);
        if (response.IsSuccessStatusCode)
        {
            message = "Shipment created successfully!";
            isError = false;
            showCreateForm = false;
            newShipment = new();
            await LoadShipments();
        }
        else
        {
            message = "Error creating shipment.";
            isError = true;
        }
    }

    private async Task UpdateStatus(int id, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus)) return;

        var response = await Http.PutAsJsonAsync($"/api/shipments/{id}/status", new { NewStatus = newStatus });
        if (response.IsSuccessStatusCode)
        {
            message = $"Status updated to {newStatus}";
            isError = false;
            await LoadShipments();
        }
        else
        {
            message = "Error updating status.";
            isError = true;
        }
    }

    private async Task DeleteShipment(int id)
    {
        var response = await Http.DeleteAsync($"/api/shipments/{id}");
        if (response.IsSuccessStatusCode)
        {
            message = "Shipment deleted.";
            isError = false;
            await LoadShipments();
        }
        else
        {
            message = "Error deleting shipment.";
            isError = true;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private class CreateShipmentModel
    {
        public string Origin { get; set; } = string.Empty;
        public string Destination { get; set; } = string.Empty;
        public string CustomerEmail { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public DateTime? EstimatedDelivery { get; set; } = DateTime.Today.AddDays(5);
    }
}

