+            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
+        }
+        catch (Exception ex)
+        {
+            message = $"Error loading shipments: {ex.Message}";
+            isError = true;
+        }
+    }
+
+    private void ShowCreateForm() => showCreateForm = true;
+    private void CancelCreate() => showCreateForm = false;
+
+    private async Task CreateShipment()
+    {
+        var request = new CreateShipmentRequest
+        {
+            Origin = newShipment.Origin,
+            Destination = newShipment.Destination,
+            CustomerEmail = newShipment.CustomerEmail,
+            Description = newShipment.Description,
+            EstimatedDelivery = newShipment.EstimatedDelivery
+        };
+
+        var response = await Http.PostAsJsonAsync("/api/shipments", request);
+        if (response.IsSuccessStatusCode)
+        {
+            message = "Shipment created successfully!";
+            isError = false;
+            showCreateForm = false;
+            newShipment = new();
+            await LoadShipments();
+        }
+        else
+        {
+            message = "Error creating shipment.";
+            isError = true;
+        }
+    }
+
+    private async Task UpdateStatus(int id, string? newStatus)
+    {
+        if (string.IsNullOrEmpty(newStatus)) return;
+
+        var response = await Http.PutAsJsonAsync($"/api/shipments/{id}/status", new { NewStatus = newStatus });
+        if (response.IsSuccessStatusCode)
+        {
+            message = $"Status updated to {newStatus}";
+            isError = false;
+            await LoadShipments();
+        }
+        else
+        {
+            message = "Error updating status.";
+            isError = true;
+        }
+    }
+
+    private async Task DeleteShipment(int id)
+    {
+        var response = await Http.DeleteAsync($"/api/shipments/{id}");
+        if (response.IsSuccessStatusCode)
+        {
+            message = "Shipment deleted.";
+            isError = false;
+            await LoadShipments();
+        }
+        else
+        {
+            message = "Error deleting shipment.";
+            isError = true;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+
+    private class CreateShipmentModel
+    {
+        public string Origin { get; set; } = string.Empty;
+        public string Destination { get; set; } = string.Empty;
+        public string CustomerEmail { get; set; } = string.Empty;
+        public string Description { get; set; } = string.Empty;
+        public DateTime? EstimatedDelivery { get; set; } = DateTime.Today.AddDays(5);
+    }
+}
