toolArgs.file_text:
@page "/track"
@using ShipmentTracker.Client.Models
@inject HttpClient Http

<PageTitle>Track Your Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p class="text-muted">Enter your tracking number to check shipment status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. SHP-20260701-100001"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<code>@searchedNumber</code>".
        Please verify your tracking number and try again.
    </div>
}

@if (result != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Tracking: <code>@result.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h6>Shipment Details</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Description</dt>
                        <dd class="col-sm-7">@result.Description</dd>

                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@result.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@result.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <h6>Delivery Information</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7">
                            <span class="badge @GetStatusBadgeClass(result.Status) fs-6">
                                @FormatStatus(result.Status)
                            </span>
                        </dd>

                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">
                            @if (result.EstimatedDelivery.HasValue)
                            {
                                @result.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")
                            }
                            else
                            {
                                <span class="text-muted">TBD</span>
                            }
                        </dd>

                        @if (result.ActualDelivery.HasValue)
                        {
                            <dt class="col-sm-5">Delivered On</dt>
                            <dd class="col-sm-7 text-success fw-bold">
                                @result.ActualDelivery.Value.ToString("MMMM dd, yyyy 'at' h:mm tt")
                            </dd>
                        }
                    </dl>
                </div>
            </div>

            <!-- Progress bar -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(result.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(result.Status)%"
                         aria-valuenow="@GetProgressPercentage(result.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(result.Status)
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string? searchedNumber;
    private TrackingResult? result;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        result = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");
            if (response.IsSuccessStatusCode)
            {
                result = await response.Content.ReadFromJsonAsync<TrackingResult>();
            }
            else
            {
                notFound = true;
            }
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

